// Vendors the Lucide icons Carlsen uses (ISC license, see vendor/lucide/LICENSE) into icons.js as inline SVG.
// No CDN: run once with a local lucide-static checkout. Usage: node tools/vendor-icons.js /path/to/lucide-static/icons
const fs = require("fs"), path = require("path");
const dir = process.argv[2] || "/tmp/vend/node_modules/lucide-static/icons";
const NAMES = ["house", "calendar-days", "plus", "layers", "book-open", "user", "chevron-right", "chevron-left", "chevron-down", "chevron-up",
  "x", "check", "timer", "info", "arrow-up", "arrow-down", "arrow-left-right", "trash-2", "ellipsis", "search", "copy", "pencil", "play",
  "dumbbell", "trending-up", "lightbulb", "rotate-ccw", "users", "flask-conical", "external-link", "arrow-right", "minus", "circle-check", "list-plus", "flag",
  "ellipsis-vertical", "repeat", "undo-2", "chart-column", "circle-user-round", "settings", "history", "calendar-check", "arrow-up-right"];
const out = {};
for (const n of NAMES) {
  const svg = fs.readFileSync(path.join(dir, n + ".svg"), "utf8");
  out[n] = svg.replace(/<!--[\s\S]*?-->/g, "").replace(/^[\s\S]*?<svg[^>]*>/, "").replace(/<\/svg>\s*$/, "").replace(/\s*\n\s*/g, "").trim();
}
const ver = JSON.parse(fs.readFileSync(path.join(dir, "..", "package.json"), "utf8")).version;
fs.writeFileSync(path.join(__dirname, "..", "icons.js"), `/* Lucide icons v${ver} (ISC license, vendor/lucide/LICENSE). Generated by tools/vendor-icons.js; do not edit. */\nwindow.ICONS = ${JSON.stringify(out, null, 0)};\n`);
console.log("icons.js:", NAMES.length, "icons, lucide", ver);
